    p5box=''
    _amt_brain={}; _amt_heart={}; _GENSLOT=set()
    _AMTKEY={'뇌출혈진단비':('b','hem'),'뇌졸증진단비':('b','infarct'),'뇌졸중진단비':('b','infarct'),'급성심근경색':('h','ami'),'뇌혈관진단비':('b','other'),'허혈성 진단비':('h','chronic')}
    for _it in rep.get('p5_own',[]):
        _v=_it.get('v')
        if not _v or _v=='미가입': continue
        _m=_AMTKEY.get(_it.get('t',''))
        if not _m: continue
        (_amt_brain if _m[0]=='b' else _amt_heart)[_m[1]]=_v
        # ★★★★★v578b 제131조 4항 — 6p 표의 key는 <b>슬롯 코드</b>(`hem`·`ami`)이지 담보명이 아니다.
        #   `_is_gen(rep,'hem')`은 언제나 False라 <b>7p가 영구히 검정</b>이었다(실측).
        #   `_AMTKEY`가 이미 담보명↔슬롯 대응을 갖고 있으므로 <b>그 담보명으로 갱신을 물어</b> 슬롯에 옮긴다.
        if _is_gen(rep, _it.get('t','')): _GENSLOT.add(_m[1])
    # ★v50(2026.07.13): 6p 심장 표 — 묶음 분해분(협심증·심부전·염증·부정맥·심근병증·판막)을
    #   dambo에서 직접 채운다. 기존엔 p5_own(급성심근·허혈성)만 실려 표가 2행만 표시됐다.
    # ★v417 빈맥(I47·48)이 빠져 있었다 — 마스터에 전용행이 있고 6p 표에도 'tachy' 행이 있는데
    #   이 맵에만 없어 <b>엑셀에 값이 있어도 6p는 영구 빈칸</b>이었다(결과값 동결 #9 위반).
    _HD={'협심증':'angina','심부전':'hf','염증':'inflam','부정맥':'arrhy',
         '심근병증':'cardiomyo','심장판막':'valve','빈맥':'tachy'}
    _dmb = rep.get('dambo') or {}
    for _k,_slot in _HD.items():
        _dv=_dmb.get(_k)
        if _dv and str(_dv) not in ('0','미가입') and _is_gen(rep,_k): _GENSLOT.add(_slot)
        if _dv and str(_dv) not in ('0','미가입') and _slot not in _amt_heart:
            _amt_heart[_slot]=_dv
    # ★CI 계약(ci status=='ci')일 때만 CI 금액 맵 구성 → 없으면 6p에 CI칸 미표시(유동)
    _cimap = rep.get('ci_amounts') or {}
    if str(rep.get('ci',{}).get('status'))!='ci': _cimap={}
    _spec = rep.get('spec_amounts') or {}
    # ★v371 제안(레드) 슬롯 산출 — 위 두 매핑을 그대로 뒤집어 쓴다(새 경로 만들지 않는다).
    _red_b=set(); _red_h=set()
    for _t,_m in _AMTKEY.items():
        _tgt=_amt_brain if _m[0]=='b' else _amt_heart
        if _m[1] in _tgt and _is_red(rep,_t):
            (_red_b if _m[0]=='b' else _red_h).add(_m[1])
    for _k,_slot in _HD.items():
        if _slot in _amt_heart and _is_red(rep,_k): _red_h.add(_slot)
    # ★★★★★v417 보유/제안 2줄 분리 — 엑셀 `보유 합계`·`제안 합계` 열이 유일 원천(결과값 동결 #9).
    #   구 값(_amt_*)은 <b>끝열 합계</b>라 보유와 제안이 이미 섞여 있었다 → 보유분으로 교체하고
    #   제안분은 별도 맵으로 넘겨 아랫줄 레드로 찍는다.
    _own417=rep.get('own_amt') or {}; _prop417=rep.get('prop_amt') or {}
    _prop_b={}; _prop_h={}
    if _own417 or _prop417:
        def _f417(v):
            try: return format(int(v),',')+'만'
            except Exception: return ''
        _SLOTNM={}
        for _t,_m in _AMTKEY.items(): _SLOTNM[(_m[0],_m[1])]=_t
        for _k,_slot in _HD.items(): _SLOTNM.setdefault(('h',_slot),_k)
        for (_ax,_slot),_nm417 in _SLOTNM.items():
            _tgt=_amt_brain if _ax=='b' else _amt_heart
            if _slot not in _tgt: continue
            _ov=_own417.get(_nm417); _pv=_prop417.get(_nm417)
            if _ov is None and _pv is None: continue
            if _ov: _tgt[_slot]=_f417(_ov)
            else:   _tgt.pop(_slot,None)
            if _pv: (_prop_b if _ax=='b' else _prop_h)[_slot]=_f417(_pv)
        _red_b-=set(_prop_b); _red_h-=set(_prop_h)
        print(f'[v417 6p] 보유/제안 2줄 분리 — 뇌 {len(_prop_b)}건 · 심장 {len(_prop_h)}건')
    # ★★★★★v376 8쪽 「주요치료비 세부」 값 산출 — 지점장 확정 2026.08.09
    #   「그 담보의 대표값 하나라도 넣어라. 보통 중환자실은 대표값의 1/2이다」
    #   대표값 = 엑셀 담보 행(암주요치료비 / 하이클래스(암) / 2대 주요치료비).
    #   대표값이 없으면 그 블록은 통째로 빈칸 — 8쪽은 유동성(회사마다 칸이 없을 수 있다).
    def _p8v(key):
        _v = (rep.get('dambo') or {}).get(key)
        if _v in (None, '', '0', '미가입'): return 0
        _s = ''.join(ch for ch in str(_v) if ch.isdigit())
        return int(_s) if _s else 0
    def _p8t(n):
        # ★값 문자열과 '만'을 분리해야 report_pptx의 _value_boxes가 좌표를 잡아
        #   진단서 PPT에서 다른 칸과 똑같이 편집할 수 있다(지점장 지시 2026.08.09).
        return (format(int(n), ',') + '<span class="dgu">만</span>') if n else ''
    _p8_cam = _p8v('암주요치료비')          # ① 암 주요치료비
    # ★★★★★v393 (2026.08.12 실측 — 지점장 「비급여주치가 안 잡힌다」):
    #   구 코드는 `'비급여주요치료비'` 키를 읽었다. 그런데 rep['dambo'] 키는
